package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

func main() {
	sem := make(chan struct{}, 2)
	var wg sync.WaitGroup
	for i := 1; i <= 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			time.Sleep(300 * time.Millisecond)
		}()
	}
	time.Sleep(50 * time.Millisecond)
	fmt.Println("goroutines right after the loop:", runtime.NumGoroutine())
	wg.Wait()
}

package main

import (
	"context"
	"errors"
	"fmt"
	"time"

	"golang.org/x/sync/errgroup"
)

func fetch(ctx context.Context, id int) error {
	time.Sleep(time.Duration(id) * 400 * time.Millisecond)
	if id == 1 {
		return errors.New("fetch 1: upstream returned 503")
	}
	return nil
}

func main() {
	start := time.Now()
	g, ctx := errgroup.WithContext(context.Background())
	for id := 1; id <= 3; id++ {
		g.Go(func() error { return fetch(ctx, id) })
	}
	err := g.Wait()
	fmt.Println("err:", err)
	fmt.Println("Wait returned after", time.Since(start).Round(200*time.Millisecond))
}
